//! The merge train (L164, Drake 2026-10-20: "speed this up without taking
//! away our rigor, make it intuitive").
//!
//! One judge run per batch instead of one per branch:
//! 1. The READY branches of one repository are read from the PR desk log in
//!    desk order (a later READY line for the same branch replaces the
//!    earlier one).
//! 2. Each is rebased in turn onto the candidate (which starts at main). A
//!    conflict only in `.crumb` files (generated by the crumb compiler) takes
//!    the candidate's copy; any other conflict skips the branch and says so.
//!    After the last branch the crumbs are recompiled once with the tool the
//!    base pins (`crumb.lock`), in one commit that touches only `.crumb`
//!    files.
//! 3. The candidate is judged ONCE by the real judge (`aien-local-ci once`).
//!    Green: a land file names the candidate sha, every branch in it and the
//!    bundle; the desk lands it as one train PR merged with
//!    `--match-head-commit`, so the merged tree is exactly the judged tree.
//!    Red: [`culprits`] names the branches that changed the failing gates'
//!    inputs; they are dropped and the rest is judged again. A gate that is
//!    already red on main blames no branch.
//!
//! Rigor kept: every verdict still comes from the judge on this machine (the
//! train never decides a gate itself), the candidate sha is the sha that is
//! judged and landed, and the operator semantics (`--operator`) pass through.
//! `--dry-run` builds the candidate in a scratch clone and judges nothing.
//!
//! `aien-test queue` prints the train state in plain words.

use crate::evidence::utc_string;
use crate::manifest;
use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Short names the desk log uses for repositories.
const ALIASES: [(&str, &str); 2] = [
    ("sc", "aien-sovereign-core"),
    ("core", "aien-sovereign-core"),
];

/// Paths whose change needs an operator run (`plan::PIPELINE_CONFIG`).
pub use crate::plan::PIPELINE_CONFIG;

/// One READY claim from the desk log.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ready {
    pub repo: String,
    pub branch: String,
    /// The sha as written (7 to 40 hex).
    pub sha: String,
    /// 1-based line number in the desk log.
    pub line: usize,
    /// The unmerged branch it is stacked on ("stacked on X", "base X"), if
    /// the desk line says so. Empty: built on main.
    pub parent: String,
}

/// The repository a desk-log token names, if any.
pub fn repo_of(token: &str, known: &BTreeSet<String>) -> Option<String> {
    let t = token
        .trim_matches(|c: char| !c.is_ascii_alphanumeric() && c != '-' && c != '/' && c != '#')
        .trim_start_matches("aien-dev/")
        .trim_start_matches("aien-spark/");
    let t = t.split('#').next().unwrap_or("");
    let t = t.strip_suffix("-mv").unwrap_or(t);
    let t = ALIASES
        .iter()
        .find(|(a, _)| *a == t)
        .map(|(_, r)| *r)
        .unwrap_or(t);
    known.contains(t).then(|| t.to_string())
}

fn is_hex_sha(s: &str) -> bool {
    (7..=40).contains(&s.len())
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn looks_like_branch(s: &str) -> bool {
    let last = s.rsplit('/').next().unwrap_or("");
    s.contains('/')
        && !s.starts_with('/')
        && !s.ends_with('/')
        && !s.starts_with('~')
        && !s.contains("//")
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"/-_.".contains(&b))
        // a file (docs/PROGRAM.md), not a branch
        && !last.contains('.')
        // a date or a score (10/10), not a branch
        && !s.bytes().all(|b| b.is_ascii_digit() || b == b'/')
}

/// Every READY claim of the desk log, in line order. A line counts when it
/// has the word `READY` (exactly) followed by a repository name; each
/// repository name after it starts one claim, which takes the first branch
/// and the first sha that follow it. "stacked on BRANCH" or "base BRANCH"
/// inside a claim names its parent branch. Scanning stops at the first
/// quoted text (the claim's test command or description).
pub fn parse_desk(text: &str, known: &BTreeSet<String>) -> Vec<Ready> {
    let mut out = Vec::new();
    for (n, line) in text.lines().enumerate() {
        if line.trim_start().starts_with("- ") {
            continue;
        }
        let toks: Vec<&str> = line.split_whitespace().collect();
        let Some(at) = toks.iter().position(|t| *t == "READY") else {
            continue;
        };
        let mut claims: Vec<Ready> = Vec::new();
        let mut parent_next = false;
        let rest = &toks[at + 1..];
        for (k, raw) in rest.iter().enumerate() {
            if raw.starts_with('"') {
                break;
            }
            if let Some(r) = repo_of(raw, known) {
                claims.push(Ready {
                    repo: r,
                    branch: String::new(),
                    sha: String::new(),
                    line: n + 1,
                    parent: String::new(),
                });
                parent_next = false;
                continue;
            }
            let Some(c) = claims.last_mut() else { continue };
            // "doc/program@3e070a25" carries both.
            let t = raw.trim_matches(|ch: char| "()[],;:\"'`".contains(ch));
            let word = t.to_ascii_lowercase();
            if (word == "stacked" && rest.get(k + 1).map(|w| w.trim_matches('(')) == Some("on"))
                || (word == "base" && !c.sha.is_empty())
            {
                parent_next = true;
                continue;
            }
            if parent_next && word != "on" {
                parent_next = false;
                if looks_like_branch(t) && c.parent.is_empty() {
                    c.parent = t.to_string();
                }
                continue;
            }
            let (b, s) = match t.split_once('@') {
                Some((b, s)) => (b, s),
                None => (t, ""),
            };
            for part in [b, s] {
                if part.is_empty() {
                    continue;
                }
                if c.sha.is_empty() && is_hex_sha(part) {
                    c.sha = part.to_string();
                } else if c.branch.is_empty() && c.sha.is_empty() && looks_like_branch(part) {
                    c.branch = part.to_string();
                }
            }
        }
        out.extend(claims.into_iter().filter(|c| !c.sha.is_empty()));
    }
    out
}

/// The claims of one repository in desk order, a later claim for the same
/// branch replacing the earlier one (it takes the later position).
pub fn queue_for(all: &[Ready], repo: &str) -> Vec<Ready> {
    let mut by: Vec<Ready> = Vec::new();
    for r in all.iter().filter(|r| r.repo == repo) {
        let key = if r.branch.is_empty() {
            &r.sha
        } else {
            &r.branch
        };
        by.retain(|o| {
            let k = if o.branch.is_empty() {
                &o.sha
            } else {
                &o.branch
            };
            k != key
        });
        by.push(r.clone());
    }
    by
}

// ---------------------------------------------------------------------------
// git
// ---------------------------------------------------------------------------

fn git(dir: &Path, args: &[&str]) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(dir)
        .args(args)
        .env("GIT_EDITOR", "true")
        .env("GIT_TERMINAL_PROMPT", "0")
        .output()
        .map_err(|e| format!("git {}: {e}", args.join(" ")))?;
    if out.status.success() {
        Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
    } else {
        Err(format!(
            "git {}: {}",
            args.join(" "),
            String::from_utf8_lossy(&out.stderr).trim()
        ))
    }
}

fn ok(dir: &Path, args: &[&str]) -> bool {
    git(dir, args).is_ok()
}

/// Paths changed by `sha` since it left `base` (merge-base diff).
pub fn changed_paths(dir: &Path, base: &str, sha: &str) -> Vec<String> {
    git(dir, &["diff", "--name-only", &format!("{base}...{sha}")])
        .map(|s| s.lines().map(str::to_string).collect())
        .unwrap_or_default()
}

// ---------------------------------------------------------------------------
// Culprits
// ---------------------------------------------------------------------------

/// Does `path` fall under a declared input (`dir/`, a file, or a `*` glob)?
pub fn under_input(path: &str, input: &str) -> bool {
    if input.contains('*') {
        return glob_match(input, path);
    }
    let i = input.trim_end_matches('/');
    path == i || path.starts_with(&format!("{i}/"))
}

fn glob_match(pat: &str, s: &str) -> bool {
    // `*` matches any run of characters (including `/`), nothing else is special.
    let parts: Vec<&str> = pat.split('*').collect();
    let mut rest = s;
    for (k, p) in parts.iter().enumerate() {
        if k == 0 {
            match rest.strip_prefix(p) {
                Some(r) => rest = r,
                None => return false,
            }
        } else if k == parts.len() - 1 {
            return rest.ends_with(p);
        } else {
            match rest.find(p) {
                Some(at) => rest = &rest[at + p.len()..],
                None => return false,
            }
        }
    }
    rest.is_empty()
}

/// One failing gate, with what the gate reads.
#[derive(Debug, Clone)]
pub struct Failing {
    pub gate: String,
    /// The gate's manifest path (repo-relative) and its declared inputs.
    pub manifest: String,
    pub inputs: Vec<String>,
}

/// The branches whose own changes touch a failing gate's inputs or its
/// manifest. A gate that is red on main (`red_on_main`) blames nobody. A
/// failing gate that declares no inputs blames every branch (it could read
/// anything). Returns branch name to the gates it is blamed for.
pub fn culprits(
    failing: &[Failing],
    changes: &[(String, Vec<String>)],
    red_on_main: &BTreeSet<String>,
) -> BTreeMap<String, Vec<String>> {
    let mut out: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for f in failing {
        if red_on_main.contains(&f.gate) {
            continue;
        }
        for (branch, paths) in changes {
            let hit = f.inputs.is_empty()
                || paths
                    .iter()
                    .any(|p| p == &f.manifest || f.inputs.iter().any(|i| under_input(p, i)));
            if hit {
                out.entry(branch.clone()).or_default().push(f.gate.clone());
            }
        }
    }
    out
}

// ---------------------------------------------------------------------------
// The candidate
// ---------------------------------------------------------------------------

/// What happened to one READY branch in this train.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Fate {
    /// In the candidate; holds the rebased tip.
    In { tip: String, commits: usize },
    /// Not in the candidate, and why, in plain words.
    Out(String),
}

#[derive(Debug, Clone)]
pub struct Entry {
    pub ready: Ready,
    pub sha: String,
    pub fate: Fate,
    pub notes: Vec<String>,
    pub changed: Vec<String>,
}

pub struct Candidate {
    pub base: String,
    pub head: String,
    pub entries: Vec<Entry>,
    pub crumb: String,
}

fn is_crumb(p: &str) -> bool {
    p == ".crumb" || p.ends_with("/.crumb")
}

/// Rebase `mb..sha` onto the current HEAD of `work`. Conflicts only in
/// `.crumb` files take the candidate's copy (the crumbs are recompiled at
/// the end). Returns the new HEAD, or why it could not.
fn rebase_onto(work: &Path, mb: &str, sha: &str) -> Result<(String, usize), String> {
    let onto = git(work, &["rev-parse", "HEAD"])?;
    git(work, &["checkout", "-q", "--detach", sha])?;
    let mut r = git(work, &["rebase", "-q", "--onto", &onto, mb]);
    let mut crumb_rounds = 0;
    while r.is_err() {
        let unmerged = git(work, &["diff", "--name-only", "--diff-filter=U"]).unwrap_or_default();
        let files: Vec<&str> = unmerged.lines().filter(|l| !l.is_empty()).collect();
        if files.is_empty() || !files.iter().all(|f| is_crumb(f)) || crumb_rounds > 200 {
            let _ = git(work, &["rebase", "--abort"]);
            let _ = git(work, &["checkout", "-q", "--detach", &onto]);
            let shown: Vec<&str> = files.iter().take(5).copied().collect();
            return Err(if files.is_empty() {
                r.unwrap_err()
            } else {
                format!(
                    "conflicts with the branches before it in: {}",
                    shown.join(", ")
                )
            });
        }
        crumb_rounds += 1;
        for f in &files {
            // During a rebase "ours" is the candidate being built on.
            git(work, &["checkout", "--ours", "--", f])?;
            git(work, &["add", "--", f])?;
        }
        r = git(work, &["-c", "core.editor=true", "rebase", "--continue"]);
        if r.is_err() && git(work, &["diff", "--cached", "--quiet"]).is_ok() {
            // The commit became empty once the crumb took the candidate's copy.
            r = git(work, &["rebase", "--skip"]);
        }
    }
    let head = git(work, &["rev-parse", "HEAD"])?;
    let n = git(work, &["rev-list", "--count", &format!("{onto}..{head}")])?
        .parse()
        .unwrap_or(0);
    Ok((head, n))
}

/// The crumb tool the candidate pins: `<tools>/<pin>/crumb`, pin from
/// `crumb.lock`. None with the reason when there is none.
fn crumb_tool(work: &Path, tools: &Path) -> Result<PathBuf, String> {
    // crumb.lock, else the aien-architecture pin of the verification
    // workflow (the same order as the rebase train, sc #639).
    let lock = fs::read_to_string(work.join("crumb.lock")).unwrap_or_default();
    let wf = fs::read_to_string(work.join(".github/workflows/aien-verification.yml"))
        .unwrap_or_default();
    let from_wf = wf
        .split("aien-architecture @ ")
        .nth(1)
        .map(|s| s.chars().take(40).collect::<String>())
        .unwrap_or_default();
    let pin = lock
        .split(|c: char| !c.is_ascii_hexdigit())
        .find(|t| t.len() == 40)
        .map(str::to_string)
        .or_else(|| (from_wf.len() == 40 && is_hex_sha(&from_wf)).then_some(from_wf))
        .ok_or("no crumb.lock and no pinned crumb tool in aien-verification.yml")?;
    let pin = pin.as_str();
    let p = tools.join(pin).join("crumb");
    if p.is_file() {
        Ok(p)
    } else {
        Err(format!(
            "crumb tool for pin {} is not built ({})",
            &pin[..12],
            p.display()
        ))
    }
}

/// Recompile the crumbs once; commit only `.crumb` changes.
fn recompile_crumbs(work: &Path, tools: &Path) -> String {
    let tool = match crumb_tool(work, tools) {
        Ok(t) => t,
        Err(e) => return format!("crumbs not recompiled: {e}"),
    };
    let run = |args: &[&str]| {
        Command::new(&tool)
            .args(args)
            .current_dir(work)
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    };
    if !run(&["compile", "."]) {
        let _ = git(work, &["checkout", "-q", "--", "."]);
        return "crumbs not recompiled: crumb compile failed".to_string();
    }
    // Tracked changes and new files (`git()` trims its output, so porcelain
    // columns would be wrong on the first line).
    let changed = [
        git(work, &["diff", "--name-only"]).unwrap_or_default(),
        git(work, &["ls-files", "--others", "--exclude-standard"]).unwrap_or_default(),
    ]
    .join("\n");
    let paths: Vec<&str> = changed.lines().filter(|l| !l.is_empty()).collect();
    if paths.is_empty() {
        return if run(&["verify", "."]) {
            "crumbs current, crumb verify OK".to_string()
        } else {
            "crumb verify FAILS on the candidate".to_string()
        };
    }
    if !paths.iter().all(|p| is_crumb(p)) {
        let _ = git(work, &["checkout", "-q", "--", "."]);
        return "crumbs not recompiled: crumb compile touched files other than .crumb".to_string();
    }
    let _ = git(work, &["add", "-A"]);
    let msg = "crumb: recompile after the merge train rebase";
    match git(work, &["commit", "-q", "-m", msg]) {
        Ok(_) if run(&["verify", "."]) => {
            format!("{} crumb files recompiled, crumb verify OK", paths.len())
        }
        Ok(_) => "crumbs recompiled but crumb verify FAILS".to_string(),
        Err(e) => format!("crumb commit failed: {e}"),
    }
}

/// Build the candidate in `work` (a scratch clone of the trusted clone):
/// main, then every queued branch rebased in turn, then one crumb commit.
/// `drop` names branches (or shas) to leave out (the culprits of an earlier
/// round), with the reason.
pub fn build(
    clone: &Path,
    work: &Path,
    base_ref: &str,
    queue: &[Ready],
    drop: &BTreeMap<String, String>,
    operator: bool,
    crumb_tools: &Path,
) -> Result<Candidate, String> {
    if !work.join(".git").exists() {
        if let Some(p) = work.parent() {
            fs::create_dir_all(p).map_err(|e| e.to_string())?;
        }
        let out = Command::new("git")
            .args(["clone", "-q", "--shared", "--no-checkout"])
            .arg(clone)
            .arg(work)
            .output()
            .map_err(|e| e.to_string())?;
        if !out.status.success() {
            return Err(format!(
                "cannot make the scratch clone: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            ));
        }
        git(work, &["config", "user.name", "aien merge train"])?;
        git(work, &["config", "user.email", "aien@aienos.com"])?;
    }
    let _ = git(work, &["rebase", "--abort"]);
    // The trusted clone's remote refs are the truth; fetch them as ours.
    git(
        work,
        &[
            "fetch",
            "-q",
            "--prune",
            "origin",
            "+refs/remotes/origin/*:refs/remotes/origin/*",
        ],
    )?;
    let base = git(
        work,
        &["rev-parse", "--verify", &format!("{base_ref}^{{commit}}")],
    )
    .map_err(|_| format!("{base_ref} is not in {}", clone.display()))?;
    git(work, &["checkout", "-q", "--force", "--detach", &base])?;
    let mut entries = Vec::new();
    for r in queue {
        let mut e = Entry {
            ready: r.clone(),
            sha: r.sha.clone(),
            fate: Fate::Out(String::new()),
            notes: Vec::new(),
            changed: Vec::new(),
        };
        let full = match git(
            work,
            &[
                "rev-parse",
                "--verify",
                "-q",
                &format!("{}^{{commit}}", r.sha),
            ],
        ) {
            Ok(s) => s,
            Err(_) => {
                e.fate = Fate::Out(
                    "its commit is not in the trusted clone (not pushed, or not fetched yet)"
                        .into(),
                );
                entries.push(e);
                continue;
            }
        };
        e.sha = full.clone();
        if !r.branch.is_empty() {
            match git(work, &["rev-parse", "-q", "--verify", &format!("refs/remotes/origin/{}", r.branch)]) {
                Ok(tip) if tip != full => e.notes.push(format!(
                    "the branch has moved since this READY line (tip {}); the train uses the READY commit",
                    &tip[..12.min(tip.len())]
                )),
                Ok(_) => {}
                Err(_) => e.notes.push("the branch is gone from origin".into()),
            }
        }
        if ok(work, &["merge-base", "--is-ancestor", &full, &base]) {
            e.fate = Fate::Out("already on main".into());
            entries.push(e);
            continue;
        }
        let cherry = git(work, &["cherry", &base, &full]).unwrap_or_default();
        if !cherry.is_empty() && cherry.lines().all(|l| l.starts_with('-')) {
            e.fate = Fate::Out("already on main (the same changes landed)".into());
            entries.push(e);
            continue;
        }
        e.changed = changed_paths(work, &base, &full);
        let key_b = if r.branch.is_empty() {
            &full
        } else {
            &r.branch
        };
        if let Some(why) = drop.get(key_b).or_else(|| drop.get(&full)) {
            e.fate = Fate::Out(why.clone());
            entries.push(e);
            continue;
        }
        let cfg: Vec<&String> = e
            .changed
            .iter()
            .filter(|p| PIPELINE_CONFIG.iter().any(|c| p.starts_with(c)))
            .collect();
        if !cfg.is_empty() && !operator {
            e.fate = Fate::Out(format!(
                "changes the judge's own setup ({}); needs an operator train (--operator)",
                cfg[0]
            ));
            entries.push(e);
            continue;
        }
        if let Some(prev) = entries
            .iter()
            .find(|p: &&Entry| p.sha == full && matches!(p.fate, Fate::In { .. }))
        {
            e.fate = Fate::Out(format!(
                "the same commit is already in the train as {}",
                label(prev)
            ));
            entries.push(e);
            continue;
        }
        // A branch stacked on another unmerged branch rides only behind its
        // parent: its own commits are parent..branch. Without the parent it
        // would bring the parent's commits in unreviewed.
        let parent_sha = if r.parent.is_empty() || r.parent == "main" {
            None
        } else {
            match entries
                .iter()
                .find(|p| p.ready.branch == r.parent && matches!(p.fate, Fate::In { .. }))
            {
                Some(p) => Some(p.sha.clone()),
                None => {
                    e.fate = Fate::Out(format!(
                        "stacked on {}, which is not in this train (it lands after its parent)",
                        r.parent
                    ));
                    entries.push(e);
                    continue;
                }
            }
        };
        let mb = match parent_sha
            .map(Ok)
            .unwrap_or_else(|| git(work, &["merge-base", &base, &full]))
        {
            Ok(m) => m,
            Err(_) => {
                e.fate = Fate::Out("shares no history with main".into());
                entries.push(e);
                continue;
            }
        };
        e.changed = changed_paths(work, &mb, &full);
        let behind: usize = git(work, &["rev-list", "--count", &format!("{mb}..{full}")])
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(0);
        if behind > 60 {
            e.notes.push(format!(
                "{behind} commits since main: probably stacked on another unmerged branch"
            ));
        }
        match rebase_onto(work, &mb, &full) {
            Ok((_, 0)) => {
                e.fate = Fate::Out("already on main (its changes are there)".into());
            }
            Ok((tip, n)) => e.fate = Fate::In { tip, commits: n },
            Err(why) => e.fate = Fate::Out(format!("did not rebase cleanly: {why}")),
        }
        entries.push(e);
    }
    let crumb = if entries.iter().any(|e| matches!(e.fate, Fate::In { .. })) {
        recompile_crumbs(work, crumb_tools)
    } else {
        "nothing in the candidate".to_string()
    };
    let head = git(work, &["rev-parse", "HEAD"])?;
    Ok(Candidate {
        base,
        head,
        entries,
        crumb,
    })
}

/// The failing gates of a judged bundle, with their manifests' inputs read
/// at the candidate.
pub fn failing_gates(work: &Path, head: &str, bundle: &Value) -> Vec<Failing> {
    let mut paths: BTreeMap<String, (String, Vec<String>)> = BTreeMap::new();
    if let Ok(list) = git(work, &["ls-tree", "-r", "--name-only", head]) {
        for p in list.lines().filter(|p| p.ends_with(".gate")) {
            if let Ok(text) = git(work, &["show", &format!("{head}:{p}")]) {
                if let Ok(m) = manifest::parse(text.as_bytes()) {
                    paths.insert(m.gate.clone(), (p.to_string(), m.inputs.clone()));
                }
            }
        }
    }
    bundle["checks"]
        .as_array()
        .map(|cs| {
            cs.iter()
                .filter(|c| c["verdict"] == "FAIL")
                .filter_map(|c| c["gate"].as_str())
                .map(|g| {
                    let (manifest, inputs) = paths.get(g).cloned().unwrap_or_default();
                    Failing {
                        gate: g.to_string(),
                        manifest,
                        inputs,
                    }
                })
                .collect()
        })
        .unwrap_or_default()
}

/// Gates that FAIL in the newest judged bundle of `base` (main is red on
/// them, so no branch is blamed for them).
pub fn red_on_main(state: &Path, repo: &str, base: &str) -> (BTreeSet<String>, String) {
    let b = state
        .join("bundles")
        .join(repo)
        .join(base)
        .join("bundle.json");
    match fs::read(&b)
        .ok()
        .and_then(|x| serde_json::from_slice::<Value>(&x).ok())
    {
        Some(v) => {
            let red: BTreeSet<String> = v["checks"]
                .as_array()
                .map(|cs| {
                    cs.iter()
                        .filter(|c| c["verdict"] == "FAIL")
                        .filter_map(|c| c["gate"].as_str().map(str::to_string))
                        .collect()
                })
                .unwrap_or_default();
            let words = if red.is_empty() {
                format!(
                    "main {} was judged {}",
                    &base[..12],
                    v["verdict"].as_str().unwrap_or("?")
                )
            } else {
                format!(
                    "main {} is red on {}",
                    &base[..12],
                    red.iter().cloned().collect::<Vec<_>>().join(", ")
                )
            };
            (red, words)
        }
        None => (
            BTreeSet::new(),
            format!("main {} has not been judged", &base[..12.min(base.len())]),
        ),
    }
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

pub const TRAIN_USAGE: &str = "usage: aien-test train REPO [--dry-run] [--operator] [--desk FILE] [--clones DIR] [--state-dir DIR] [--base REF] [--judge CMD] [--rounds N]
       aien-test queue [REPO]... [--desk FILE] [--clones DIR] [--state-dir DIR]";

pub fn is_train_command(c: &str) -> bool {
    c == "train" || c == "queue"
}

struct Args {
    repos: Vec<String>,
    dry_run: bool,
    operator: bool,
    desk: PathBuf,
    clones: PathBuf,
    state: PathBuf,
    base: String,
    judge: String,
    rounds: usize,
}

fn home() -> PathBuf {
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_default()
}

fn parse(argv: &[String]) -> Result<Args, String> {
    let h = home();
    let mut a = Args {
        repos: Vec::new(),
        dry_run: false,
        operator: false,
        desk: h.join("handoffs/2026-10-18-pr-desk.md"),
        clones: h.join("workspace/pipeline/clones"),
        state: h.join(".local/state/aien-local-ci"),
        base: "origin/main".into(),
        judge: h.join(".local/bin/aien-local-ci").display().to_string(),
        rounds: 4,
    };
    let mut it = argv.iter().skip(1);
    while let Some(x) = it.next() {
        let mut val = || {
            it.next()
                .cloned()
                .ok_or_else(|| format!("{x} needs a value"))
        };
        match x.as_str() {
            "--dry-run" => a.dry_run = true,
            "--operator" => a.operator = true,
            "--desk" => a.desk = PathBuf::from(val()?),
            "--clones" => a.clones = PathBuf::from(val()?),
            "--state-dir" => a.state = PathBuf::from(val()?),
            "--base" => a.base = val()?,
            "--judge" => a.judge = val()?,
            "--rounds" => a.rounds = val()?.parse().map_err(|_| "--rounds needs a number")?,
            s if s.starts_with("--") => return Err(format!("unknown argument {s:?}")),
            s => a.repos.push(s.to_string()),
        }
    }
    Ok(a)
}

fn known_repos(clones: &Path) -> BTreeSet<String> {
    fs::read_dir(clones)
        .map(|rd| {
            rd.flatten()
                .filter(|e| e.path().join(".git").exists() || e.path().join("HEAD").exists())
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default()
}

fn short(s: &str) -> &str {
    &s[..12.min(s.len())]
}

fn label(e: &Entry) -> String {
    if e.ready.branch.is_empty() {
        short(&e.sha).to_string()
    } else {
        format!("{} ({})", e.ready.branch, short(&e.sha))
    }
}

fn state_json(repo: &str, c: &Candidate, round: usize, verdict: &str, extra: Value) -> Value {
    json!({
        "schema": "aien-train/1",
        "repo": repo,
        "utc": utc_string(std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0)),
        "round": round,
        "base": c.base,
        "candidate": c.head,
        "crumb": c.crumb,
        "verdict": verdict,
        "entries": c.entries.iter().map(|e| json!({
            "branch": e.ready.branch,
            "ready_sha": e.sha,
            "desk_line": e.ready.line,
            "in": matches!(e.fate, Fate::In { .. }),
            "tip": match &e.fate { Fate::In { tip, .. } => json!(tip), _ => Value::Null },
            "why_out": match &e.fate { Fate::Out(w) => json!(w), _ => Value::Null },
            "notes": e.notes,
        })).collect::<Vec<_>>(),
        "extra": extra,
    })
}

fn print_candidate(repo: &str, c: &Candidate, main_words: &str) {
    let n_in = c
        .entries
        .iter()
        .filter(|e| matches!(e.fate, Fate::In { .. }))
        .count();
    println!("Train for {repo}: {main_words}.");
    println!(
        "Candidate {} = main {} + {} branch(es), one judge run. {}",
        short(&c.head),
        short(&c.base),
        n_in,
        c.crumb
    );
    for e in &c.entries {
        match &e.fate {
            Fate::In { tip, commits } => println!(
                "  IN    {}  -> {} ({} commit(s), desk line {})",
                label(e),
                short(tip),
                commits,
                e.ready.line
            ),
            Fate::Out(why) => println!("  OUT   {}  {}", label(e), why),
        }
        for n in &e.notes {
            println!("        note: {n}");
        }
    }
}

fn judge(a: &Args, repo: &str, work: &Path, head: &str) -> Result<Value, String> {
    // Make the candidate's objects present in the trusted clone, held by a
    // ref so gc keeps them; then the real judge runs it like any head.
    let clone = a.clones.join(repo);
    let refname = format!("+{head}:refs/aien-train/{repo}");
    git(
        &clone,
        &["fetch", "-q", &work.display().to_string(), &refname],
    )?;
    let mut cmd = Command::new(&a.judge);
    cmd.args(["once", repo, head]);
    if a.operator {
        cmd.arg("--operator");
    }
    let st = cmd
        .status()
        .map_err(|e| format!("cannot start the judge: {e}"))?;
    let b = a
        .state
        .join("bundles")
        .join(repo)
        .join(head)
        .join("bundle.json");
    let v: Value = fs::read(&b)
        .ok()
        .and_then(|x| serde_json::from_slice(&x).ok())
        .ok_or_else(|| format!("the judge left no bundle (exit {:?})", st.code()))?;
    Ok(v)
}

pub fn cli_main(argv: &[String]) -> i32 {
    let a = match parse(argv) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("aien-test {}: {e}\n{TRAIN_USAGE}", argv[0]);
            return 2;
        }
    };
    let known = known_repos(&a.clones);
    let desk = fs::read_to_string(&a.desk).unwrap_or_default();
    let all = parse_desk(&desk, &known);
    if argv[0] == "queue" {
        return queue_page(&a, &all, &known);
    }
    let [repo] = a.repos.as_slice() else {
        eprintln!("{TRAIN_USAGE}");
        return 2;
    };
    if !known.contains(repo) {
        eprintln!(
            "aien-test train: no trusted clone {}",
            a.clones.join(repo).display()
        );
        return 2;
    }
    let queue = queue_for(&all, repo);
    let clone = a.clones.join(repo);
    let work = a.state.join("train").join(format!("{repo}.work"));
    let tools = a.state.join("crumb-tools");
    let state_file = a.state.join("train").join(format!("{repo}.json"));
    let mut dropped: BTreeMap<String, String> = BTreeMap::new();
    for round in 1..=a.rounds.max(1) {
        let c = match build(&clone, &work, &a.base, &queue, &dropped, a.operator, &tools) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("aien-test train: {e}");
                return 1;
            }
        };
        let (red, main_words) = red_on_main(&a.state, repo, &c.base);
        print_candidate(repo, &c, &main_words);
        let n_in = c
            .entries
            .iter()
            .filter(|e| matches!(e.fate, Fate::In { .. }))
            .count();
        if a.dry_run || n_in == 0 {
            let verdict = if a.dry_run { "DRY_RUN" } else { "EMPTY" };
            let _ = fs::write(
                &state_file,
                format!("{}\n", state_json(repo, &c, round, verdict, json!({}))),
            );
            println!(
                "{}",
                if a.dry_run {
                    "Dry run: nothing judged, nothing pushed."
                } else {
                    "Nothing to judge."
                }
            );
            return 0;
        }
        let _ = fs::write(
            &state_file,
            format!("{}\n", state_json(repo, &c, round, "JUDGING", json!({}))),
        );
        let bundle = match judge(&a, repo, &work, &c.head) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("aien-test train: {e}");
                return 1;
            }
        };
        let verdict = bundle["verdict"].as_str().unwrap_or("?").to_string();
        if verdict == "PASS" {
            let land = state_json(
                repo,
                &c,
                round,
                "PASS",
                json!({
                    "land": "push the candidate as branch train/<repo>, open one train PR, merge it with --match-head-commit (merge commit: the merged tree is the judged tree), then close every IN branch's PR as merged in it",
                    "bundle": a.state.join("bundles").join(repo).join(&c.head).join("bundle.json"),
                }),
            );
            let _ = fs::write(&state_file, format!("{land}\n"));
            let _ = fs::write(
                a.state.join("train").join(format!("{repo}.land.json")),
                format!("{land}\n"),
            );
            println!(
                "Judged PASS. Land file for the desk: {}",
                a.state
                    .join("train")
                    .join(format!("{repo}.land.json"))
                    .display()
            );
            return 0;
        }
        let failing = failing_gates(&work, &c.head, &bundle);
        let changes: Vec<(String, Vec<String>)> = c
            .entries
            .iter()
            .filter(|e| matches!(e.fate, Fate::In { .. }))
            .map(|e| {
                (
                    if e.ready.branch.is_empty() {
                        e.sha.clone()
                    } else {
                        e.ready.branch.clone()
                    },
                    e.changed.clone(),
                )
            })
            .collect();
        let blamed = culprits(&failing, &changes, &red);
        let _ = fs::write(
            &state_file,
            format!(
                "{}\n",
                state_json(
                    repo,
                    &c,
                    round,
                    &verdict,
                    json!({ "failing": failing.iter().map(|f| &f.gate).collect::<Vec<_>>(), "blamed": blamed })
                )
            ),
        );
        if blamed.is_empty() {
            println!(
                "Judged {verdict}; no branch changed the failing gates' inputs ({}): main or the machine is red there. Train stops.",
                failing.iter().map(|f| f.gate.as_str()).collect::<Vec<_>>().join(", ")
            );
            return 1;
        }
        for (b, gates) in &blamed {
            println!("  dropped {b}: it changed what {} reads", gates.join(", "));
            dropped.insert(
                b.clone(),
                format!(
                    "dropped in round {round}: it changed what {} reads",
                    gates.join(", ")
                ),
            );
        }
    }
    println!("Train stopped after {} rounds.", a.rounds);
    1
}

/// `aien-test queue`: one page, plain words.
fn queue_page(a: &Args, all: &[Ready], known: &BTreeSet<String>) -> i32 {
    let repos: Vec<String> = if a.repos.is_empty() {
        let mut r: Vec<String> = all
            .iter()
            .map(|r| r.repo.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        r.retain(|x| known.contains(x));
        r
    } else {
        a.repos.clone()
    };
    for repo in &repos {
        let clone = a.clones.join(repo);
        let main = git(&clone, &["rev-parse", &a.base]).unwrap_or_default();
        let (_, words) = red_on_main(&a.state, repo, &main);
        println!("{repo}: {words}.");
        let st: Option<Value> = fs::read(a.state.join("train").join(format!("{repo}.json")))
            .ok()
            .and_then(|x| serde_json::from_slice(&x).ok());
        if let Some(s) = &st {
            let n_in = s["entries"]
                .as_array()
                .map(|e| e.iter().filter(|x| x["in"] == true).count())
                .unwrap_or(0);
            println!(
                "  Train: candidate {} with {} branch(es), {} ({}, round {}).",
                short(s["candidate"].as_str().unwrap_or("")),
                n_in,
                match s["verdict"].as_str().unwrap_or("") {
                    "DRY_RUN" => "built in a dry run, not judged",
                    "JUDGING" => "being judged now",
                    "PASS" => "judged PASS, waiting for the desk to land it",
                    "EMPTY" => "nothing to judge",
                    _ => "judged red",
                },
                s["utc"].as_str().unwrap_or(""),
                s["round"]
            );
            let hv = a.state.join("interim").join(format!(
                "{repo}.{}.json",
                s["candidate"].as_str().unwrap_or("")
            ));
            if let Some(v) = fs::read(&hv)
                .ok()
                .and_then(|x| serde_json::from_slice::<Value>(&x).ok())
            {
                println!(
                    "  Host gates: {} ({} gates); silicon gates still queued: {}.",
                    v["host_verdict"].as_str().unwrap_or("?"),
                    v["host_gates"],
                    v["silicon_left"].as_array().map(|x| x.len()).unwrap_or(0)
                );
            }
        }
        // What is waiting and why, in desk order.
        let entries: BTreeMap<String, Value> = st
            .as_ref()
            .and_then(|s| s["entries"].as_array().cloned())
            .unwrap_or_default()
            .into_iter()
            .map(|e| (e["ready_sha"].as_str().unwrap_or("").to_string(), e))
            .collect();
        for r in queue_for(all, repo) {
            let full = git(
                &clone,
                &[
                    "rev-parse",
                    "-q",
                    "--verify",
                    &format!("{}^{{commit}}", r.sha),
                ],
            )
            .unwrap_or_default();
            let what = match entries.get(&full) {
                Some(e) if e["in"] == true => "in the candidate".to_string(),
                Some(e) => e["why_out"].as_str().unwrap_or("left out").to_string(),
                None if full.is_empty() => "commit not in the trusted clone yet".to_string(),
                None if ok(&clone, &["merge-base", "--is-ancestor", &full, &main]) => {
                    "already on main".to_string()
                }
                None => {
                    // Its own judge run, if any: the host note, then the bundle.
                    let b = a
                        .state
                        .join("bundles")
                        .join(repo)
                        .join(&full)
                        .join("bundle.json");
                    let hv = a.state.join("interim").join(format!("{repo}.{full}.json"));
                    match (
                        fs::read(&b)
                            .ok()
                            .and_then(|x| serde_json::from_slice::<Value>(&x).ok()),
                        fs::read(&hv)
                            .ok()
                            .and_then(|x| serde_json::from_slice::<Value>(&x).ok()),
                    ) {
                        (Some(v), _) => {
                            format!("judged alone: {}", v["verdict"].as_str().unwrap_or("?"))
                        }
                        (None, Some(h)) => format!(
                            "host {}, silicon queued {}",
                            h["host_verdict"].as_str().unwrap_or("?"),
                            h["silicon_left"].as_array().map(|x| x.len()).unwrap_or(0)
                        ),
                        (None, None) => "waiting for the next train".to_string(),
                    }
                }
            };
            let name = if r.branch.is_empty() {
                short(&r.sha).to_string()
            } else {
                r.branch.clone()
            };
            println!("  - {name}: {what}");
        }
    }
    0
}

#[cfg(test)]
mod tests {
    use super::*;

    fn known() -> BTreeSet<String> {
        ["omega", "aien-sovereign-core", "aienos", "physics"]
            .iter()
            .map(|s| s.to_string())
            .collect()
    }

    #[test]
    fn desk_lines_in_their_many_shapes() {
        let text = "\
READY aienos-mv feat/allen-canvas 3ece0206d94b6de39fc96de4b17752c7f0c340e6 \"sh scripts/x.sh\"
2026-10-19T23:53Z READY doc/program@3e070a2576779c2aea421694fd25c1c06907224c omega-mv docs/PROGRAM.md
READY 2026-10-19 aien-dev/omega-mv fix/tcgemm-nj @ 35eecb3ce20751ed46ca2b66f2811b0765c71754 (L149): text
2026-10-20T04:23:09Z hermes-desk(sc lane) OPENED sc# fix/gb10-gate-prepare 85e0cb95 (L154 READY: gb10 gate
- feat/imac-gpu-core READY above (e51a468) is SUPERSEDED by 8093baa
2026-10-20T07:43:06Z L129 READY aien-sovereign-core speed5/batching aac748136b3d2cccd180a940dc3152392b1e6691 (stacked on cascade/continuous-batching 7e69aeda) + omega speed5/handle-slots 66e84cf6a0d2b4aa092f86d6ef383e5aa41ac758 (stacked on x)
fixer(L160) READY omega fix/r14-recovery-flake e5404a05 R14 flake
READY physics doc/driver-floor 30cf10a \"docs/numeric/DRIVER_FLOOR.md 8 calls\"
";
        let r = parse_desk(text, &known());
        let got: Vec<(String, String, String)> = r
            .iter()
            .map(|x| (x.repo.clone(), x.branch.clone(), x.sha[..7].to_string()))
            .collect();
        assert_eq!(
            got,
            vec![
                ("aienos".into(), "feat/allen-canvas".into(), "3ece020".into()),
                ("omega".into(), "fix/tcgemm-nj".into(), "35eecb3".into()),
                ("aien-sovereign-core".into(), "speed5/batching".into(), "aac7481".into()),
                ("omega".into(), "speed5/handle-slots".into(), "66e84cf".into()),
                ("omega".into(), "fix/r14-recovery-flake".into(), "e5404a0".into()),
                ("physics".into(), "doc/driver-floor".into(), "30cf10a".into()),
            ],
            "the doc/program line names its repo after the sha, so it is skipped; READY: and notes are not claims"
        );
        assert_eq!(r[2].parent, "cascade/continuous-batching");
        assert_eq!(r[0].parent, "");
    }

    #[test]
    fn a_later_ready_line_replaces_the_earlier_one_and_takes_its_place() {
        let text =
            "READY omega a/one 1111111\nREADY omega b/two 2222222\nREADY omega a/one 3333333\n";
        let q = queue_for(&parse_desk(text, &known()), "omega");
        let got: Vec<(&str, &str)> = q
            .iter()
            .map(|r| (r.branch.as_str(), r.sha.as_str()))
            .collect();
        assert_eq!(got, vec![("b/two", "2222222"), ("a/one", "3333333")]);
    }

    #[test]
    fn inputs_match_dirs_files_and_globs() {
        assert!(under_input("src/a/b.c", "src/"));
        assert!(under_input("src/a/b.c", "src"));
        assert!(!under_input("srcx/a.c", "src/"));
        assert!(under_input("Makefile", "Makefile"));
        assert!(under_input("mk/x.mk", "mk/*.mk"));
        assert!(!under_input("mk/x.c", "mk/*.mk"));
    }

    fn f(gate: &str, inputs: &[&str]) -> Failing {
        Failing {
            gate: gate.into(),
            manifest: format!("tests/gates/{}.gate", gate.to_lowercase()),
            inputs: inputs.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn the_culprit_is_the_branch_that_changed_the_failing_gates_inputs() {
        let changes = vec![
            ("docs/a".to_string(), vec!["docs/A.md".to_string()]),
            ("fix/b".to_string(), vec!["src/ans/x.c".to_string()]),
            (
                "gate/c".to_string(),
                vec!["tests/gates/g-two.gate".to_string()],
            ),
        ];
        let failing = vec![
            f("G-ONE", &["src/ans/", "Makefile"]),
            f("G-TWO", &["data/"]),
        ];
        let b = culprits(&failing, &changes, &BTreeSet::new());
        assert_eq!(
            b.keys().cloned().collect::<Vec<_>>(),
            vec!["fix/b", "gate/c"]
        );
        assert_eq!(b["fix/b"], vec!["G-ONE"]);
        assert_eq!(
            b["gate/c"],
            vec!["G-TWO"],
            "changing the gate file itself blames"
        );
        // Red on main: nobody is blamed for it.
        let red: BTreeSet<String> = ["G-ONE".to_string()].into_iter().collect();
        let b = culprits(&failing, &changes, &red);
        assert_eq!(b.keys().cloned().collect::<Vec<_>>(), vec!["gate/c"]);
        // A failing gate with no inputs could read anything: everyone.
        let b = culprits(&[f("G-X", &[])], &changes, &BTreeSet::new());
        assert_eq!(b.len(), 3);
    }

    use crate::testutil::{git as tgit, init_repo, write_file, TempDir};

    #[test]
    fn the_candidate_rebases_in_order_skips_a_conflict_and_takes_main_for_crumb_conflicts() {
        let repo = init_repo(
            "train-repo",
            &[
                ("a.txt", "a\n", false),
                ("b.txt", "b\n", false),
                (".crumb", "c0\n", false),
            ],
        );
        let r = repo.path();
        tgit(r, &["branch", "-M", "main"]);
        let main = runner_head(r);
        let mk = |name: &str, file: &str, text: &str, crumb: Option<&str>| -> String {
            tgit(r, &["checkout", "-q", "-b", name, &main]);
            write_file(r, file, text, false);
            if let Some(c) = crumb {
                write_file(r, ".crumb", c, false);
            }
            tgit(r, &["add", "-A"]);
            tgit(r, &["commit", "-q", "-m", name]);
            runner_head(r)
        };
        let one = mk("f/one", "a.txt", "a1\n", Some("c1\n"));
        let two = mk("f/two", "b.txt", "b2\n", Some("c2\n")); // crumb-only conflict with one
        let three = mk("f/three", "a.txt", "a3\n", None); // real conflict with one
                                                          // f/kid is stacked on f/one: it rides only behind it.
        tgit(r, &["checkout", "-q", "-b", "f/kid", &one]);
        write_file(r, "c.txt", "kid\n", false);
        tgit(r, &["add", "-A"]);
        tgit(r, &["commit", "-q", "-m", "kid"]);
        let kid = runner_head(r);
        tgit(r, &["checkout", "-q", "main"]);
        // The trusted clone layout: refs/remotes/origin/* in the clone.
        let clone = TempDir::new("train-clone");
        tgit(clone.path(), &["init", "-q"]);
        tgit(
            clone.path(),
            &[
                "fetch",
                "-q",
                &r.display().to_string(),
                "+refs/heads/*:refs/remotes/origin/*",
            ],
        );
        let q = vec![
            Ready {
                repo: "x".into(),
                branch: "f/one".into(),
                sha: one.clone(),
                line: 1,
                parent: String::new(),
            },
            Ready {
                repo: "x".into(),
                branch: "f/two".into(),
                sha: two.clone(),
                line: 2,
                parent: String::new(),
            },
            Ready {
                repo: "x".into(),
                branch: "f/three".into(),
                sha: three.clone(),
                line: 3,
                parent: String::new(),
            },
            Ready {
                repo: "x".into(),
                branch: "f/main".into(),
                sha: main.clone(),
                line: 4,
                parent: String::new(),
            },
            Ready {
                repo: "x".into(),
                branch: "f/kid".into(),
                sha: kid.clone(),
                line: 5,
                parent: "f/one".into(),
            },
            Ready {
                repo: "x".into(),
                branch: "f/orphan".into(),
                sha: three.clone(),
                line: 6,
                parent: "f/gone".into(),
            },
        ];
        let work = TempDir::new("train-work");
        let w = work.path().join("w");
        let tools = TempDir::new("train-tools");
        let c = build(
            clone.path(),
            &w,
            "origin/main",
            &q,
            &BTreeMap::new(),
            false,
            tools.path(),
        )
        .unwrap();
        assert!(
            matches!(c.entries[0].fate, Fate::In { .. }),
            "{:?}",
            c.entries[0].fate
        );
        assert!(
            matches!(c.entries[1].fate, Fate::In { .. }),
            "crumb-only conflict resolved: {:?}",
            c.entries[1].fate
        );
        match &c.entries[2].fate {
            Fate::Out(w) => assert!(w.contains("a.txt"), "{w}"),
            other => panic!("expected a skip, got {other:?}"),
        }
        assert_eq!(c.entries[3].fate, Fate::Out("already on main".into()));
        match &c.entries[4].fate {
            Fate::In { commits, .. } => assert_eq!(*commits, 1, "only the kid's own commit"),
            other => panic!("kid: {other:?}"),
        }
        assert!(
            matches!(&c.entries[5].fate, Fate::Out(w) if w.contains("f/gone")),
            "{:?}",
            c.entries[5].fate
        );
        assert_eq!(c.entries[4].changed, vec!["c.txt".to_string()]);
        assert!(c.crumb.contains("no crumb.lock"), "{}", c.crumb);
        // The candidate has both changes, main's crumb side (one's), on main.
        let show = |p: &str| git(&w, &["show", &format!("{}:{p}", c.head)]).unwrap();
        assert_eq!(show("a.txt"), "a1");
        assert_eq!(show("b.txt"), "b2");
        assert_eq!(show(".crumb"), "c1");
        assert!(ok(&w, &["merge-base", "--is-ancestor", &main, &c.head]));
        // Dropping a culprit rebuilds without it.
        let drop: BTreeMap<String, String> = [("f/one".to_string(), "dropped".to_string())]
            .into_iter()
            .collect();
        let c2 = build(
            clone.path(),
            &w,
            "origin/main",
            &q,
            &drop,
            false,
            tools.path(),
        )
        .unwrap();
        assert_eq!(c2.entries[0].fate, Fate::Out("dropped".into()));
        assert!(
            matches!(c2.entries[2].fate, Fate::In { .. }),
            "three no longer conflicts: {:?}",
            c2.entries[2].fate
        );
        assert!(
            matches!(&c2.entries[4].fate, Fate::Out(w) if w.contains("not in this train")),
            "the kid leaves with its parent"
        );
    }

    fn runner_head(r: &Path) -> String {
        git(r, &["rev-parse", "HEAD"]).unwrap()
    }
}
